     "e": "`sorted(a + b)` works but is O((n+m) log(n+m)) and ignores the fact that the inputs are already sorted.",
     "code": "import heapq\n\ndef merge(a, b):\n    i = j = 0\n    out = []\n    while i < len(a) and j < len(b):\n        if a[i] <= b[j]:\n            out.append(a[i]); i += 1\n        else:\n            out.append(b[j]); j += 1\n    return out + a[i:] + b[j:]\n\nprint(merge([1, 4, 9], [2, 3, 10, 11]))\nprint(list(heapq.merge([1, 4], [2, 3], [0])))",
